SELECT country, COUNT(*) AS customers, MIN(first_order_date) AS first, MAX(last_order_date) AS last
FROM gold.customer_lifetime
WHERE country ILIKE 'turkey'
GROUP BY country;

SELECT country, COUNT(*) AS customers
FROM gold.customer_lifetime
WHERE first_order_date <= DATE '2026-09-30'
GROUP BY country
ORDER BY country;

SELECT MIN(first_order_date), MAX(last_order_date) FROM gold.customer_lifetime;

SELECT COUNT(*) AS customers
FROM gold.customer_lifetime
WHERE country = 'TR' AND first_order_date <= DATE '2026-09-30';

SELECT table_name, column_name, data_type FROM information_schema.columns 
WHERE table_name IN ('exposed.daily_sales_with_weather','exposed.net_sales_daily','gold.daily_sales','legacy.daily_net_sales','exposed.sales_by_country_daily')
ORDER BY table_name, ordinal_position;

SELECT table_name, column_name, data_type FROM information_schema.columns 
WHERE table_name LIKE '%sales%' OR table_name LIKE '%net_sales%'
ORDER BY table_name, ordinal_position;

SELECT SUM(net_revenue_eur) AS net_revenue_eur, COUNT(*) AS days
FROM exposed.net_sales_daily
WHERE order_date BETWEEN DATE '2026-10-01' AND DATE '2026-10-10';

SELECT SUM(net_revenue) AS net_revenue, COUNT(*) AS days
FROM legacy.daily_net_sales
WHERE sales_date BETWEEN DATE '2026-10-01' AND DATE '2026-10-10';

SELECT activity_date, engaged_customers_7d
FROM gold.customer_engagement_daily
WHERE activity_date = DATE '2026-10-03';

SELECT DISTINCT country
FROM exposed.sales_by_country_daily
ORDER BY country;

SELECT table_schema, table_name, column_name, data_type
FROM information_schema.columns
WHERE (table_schema, table_name) IN (
  ('gold','daily_sales'),('exposed','daily_sales_with_weather'),('exposed','net_sales_daily'),('legacy','daily_net_sales')
)
ORDER BY table_schema, table_name, ordinal_position;

SELECT sum(revenue_eur) AS total_revenue_eur, count(*) AS days_count
FROM gold.daily_sales
WHERE order_date BETWEEN DATE '2026-09-25' AND DATE '2026-10-01';

SELECT table_schema, table_name, column_name
FROM information_schema.columns
WHERE column_name ILIKE '%cancel%' OR column_name ILIKE '%return%';

SELECT SUM(revenue_eur) AS total_gmv
FROM gold.daily_sales
WHERE order_date >= DATE '2026-09-01' AND order_date <= DATE '2026-09-30';

SELECT MIN(activity_date), MAX(activity_date), COUNT(*) AS days
FROM gold.customer_engagement_daily;
SELECT activity_date, cart_sessions, checkout_sessions, cart_to_checkout_rate
FROM gold.customer_engagement_daily
WHERE activity_date BETWEEN DATE '2026-09-20' AND DATE '2026-10-03'
ORDER BY activity_date;

SELECT activity_date, cart_sessions, checkout_sessions, cart_to_checkout_rate
FROM gold.customer_engagement_daily
ORDER BY activity_date;

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'exposed' AND table_name = 'net_sales_daily';

SELECT column_name, data_type
FROM information_schema.columns
WHERE table_schema = 'exposed' AND table_name = 'daily_sales_with_weather';

SELECT DISTINCT channel
FROM gold.customer_actions_daily
ORDER BY channel;

SELECT table_schema, table_name, column_name, data_type
FROM information_schema.columns
WHERE (table_schema, table_name) IN (
  ('gold','daily_sales'), ('exposed','net_sales_daily'), ('exposed','daily_sales_with_weather'), ('exposed','sales_by_country_daily'), ('legacy','daily_net_sales')
)
ORDER BY table_schema, table_name, ordinal_position;
